            case "001":
                assertEquals(record.getCurrentLocation().getFileId(), FSUtils.getFileId(filename2));
                assertEquals(((TestRawTripPayload) record.getData()).getJsonData(), rowChange2.getJsonData());
                break;
            case "002":
