@Test
public void testRollingStatsWithSmallFileHandling() throws Exception {
    HoodieWriteConfig cfg = getConfigBuilder(false, IndexType.INMEMORY).withAutoCommit(false).build();
    try (HoodieWriteClient client = getWriteClient(cfg)) {
        HoodieTableMetaClient metaClient = new HoodieTableMetaClient(jsc.hadoopConfiguration(), basePath);
        Map<String, Long> fileIdToInsertsMap = new HashMap<>();
        Map<String, Long> fileIdToUpsertsMap = new HashMap<>();
        String commitTime = "000";
        client.startCommitWithTime(commitTime);
        List<HoodieRecord> records = dataGen.generateInserts(commitTime, 200);
        JavaRDD<HoodieRecord> writeRecords = jsc.parallelize(records, 1);
        JavaRDD<WriteStatus> statuses = client.insert(writeRecords, commitTime);
        assertTrue("Commit should succeed", client.commit(commitTime, statuses));
        // Read from commit file
        HoodieTable table = HoodieTable.getHoodieTable(metaClient, cfg, jsc);
        HoodieCommitMetadata metadata = HoodieCommitMetadata.fromBytes(table.getActiveTimeline().getInstantDetails(table.getActiveTimeline().getDeltaCommitTimeline().lastInstant().get()).get(), HoodieCommitMetadata.class);
        HoodieRollingStatMetadata rollingStatMetadata = HoodieCommitMetadata.fromBytes(metadata.getExtraMetadata().get(HoodieRollingStatMetadata.ROLLING_STAT_METADATA_KEY).getBytes(), HoodieRollingStatMetadata.class);
        int inserts = 0;
        for (Map.Entry<String, Map<String, HoodieRollingStat>> pstat : rollingStatMetadata.getPartitionToRollingStats().entrySet()) {
            for (Map.Entry<String, HoodieRollingStat> stat : pstat.getValue().entrySet()) {
                inserts += stat.getValue().getInserts();
                fileIdToInsertsMap.put(stat.getKey(), stat.getValue().getInserts());
                fileIdToUpsertsMap.put(stat.getKey(), stat.getValue().getUpserts());
            }
        }
        Assert.assertEquals(inserts, 200);
        commitTime = "001";
        client.startCommitWithTime(commitTime);
        // generate updates + inserts. inserts should be handled into small files
        records = dataGen.generateUpdates(commitTime, records);
        records.addAll(dataGen.generateInserts(commitTime, 200));
        writeRecords = jsc.parallelize(records, 1);
        statuses = client.upsert(writeRecords, commitTime);
        assertTrue("Commit should succeed", client.commit(commitTime, statuses));
        // Read from commit file
        table = HoodieTable.getHoodieTable(metaClient, cfg, jsc);
        metadata = HoodieCommitMetadata.fromBytes(table.getActiveTimeline().getInstantDetails(table.getActiveTimeline().getDeltaCommitTimeline().lastInstant().get()).get(), HoodieCommitMetadata.class);
        rollingStatMetadata = HoodieCommitMetadata.fromBytes(metadata.getExtraMetadata().get(HoodieRollingStatMetadata.ROLLING_STAT_METADATA_KEY).getBytes(), HoodieRollingStatMetadata.class);
        inserts = 0;
        int upserts = 0;
        for (Map.Entry<String, Map<String, HoodieRollingStat>> pstat : rollingStatMetadata.getPartitionToRollingStats().entrySet()) {
            for (Map.Entry<String, HoodieRollingStat> stat : pstat.getValue().entrySet()) {
                // No new file id should be created, all the data should be written to small files already there
                assertTrue(fileIdToInsertsMap.containsKey(stat.getKey()));
                assertTrue(fileIdToUpsertsMap.containsKey(stat.getKey()));
                inserts += stat.getValue().getInserts();
                upserts += stat.getValue().getUpserts();
            }
        }
        Assert.assertEquals(inserts, 400);
        Assert.assertEquals(upserts, 200);
        // Test small file handling after compaction
        commitTime = "002";
        client.scheduleCompactionAtInstant(commitTime, Option.of(metadata.getExtraMetadata()));
        statuses = client.compact(commitTime);
        client.commitCompaction(commitTime, statuses, Option.empty());
        // Read from commit file
        table = HoodieTable.getHoodieTable(metaClient, cfg, jsc);
        metadata = HoodieCommitMetadata.fromBytes(table.getActiveTimeline().getInstantDetails(table.getActiveTimeline().getCommitsTimeline().lastInstant().get()).get(), HoodieCommitMetadata.class);
        HoodieRollingStatMetadata rollingStatMetadata1 = HoodieCommitMetadata.fromBytes(metadata.getExtraMetadata().get(HoodieRollingStatMetadata.ROLLING_STAT_METADATA_KEY).getBytes(), HoodieRollingStatMetadata.class);
        // Ensure that the rolling stats from the extra metadata of delta commits is copied over to the compaction commit
        for (Map.Entry<String, Map<String, HoodieRollingStat>> entry : rollingStatMetadata.getPartitionToRollingStats().entrySet()) {
            Assert.assertTrue(rollingStatMetadata1.getPartitionToRollingStats().containsKey(entry.getKey()));
            Assert.assertEquals(rollingStatMetadata1.getPartitionToRollingStats().get(entry.getKey()).size(), entry.getValue().size());
        }
        // Write inserts + updates
        commitTime = "003";
        client.startCommitWithTime(commitTime);
        // generate updates + inserts. inserts should be handled into small files
        records = dataGen.generateUpdates(commitTime, records);
        records.addAll(dataGen.generateInserts(commitTime, 200));
        writeRecords = jsc.parallelize(records, 1);
        statuses = client.upsert(writeRecords, commitTime);
        assertTrue("Commit should succeed", client.commit(commitTime, statuses));
        // Read from commit file
        table = HoodieTable.getHoodieTable(metaClient, cfg, jsc);
        metadata = HoodieCommitMetadata.fromBytes(table.getActiveTimeline().getInstantDetails(table.getActiveTimeline().getDeltaCommitTimeline().lastInstant().get()).get(), HoodieCommitMetadata.class);
        rollingStatMetadata = HoodieCommitMetadata.fromBytes(metadata.getExtraMetadata().get(HoodieRollingStatMetadata.ROLLING_STAT_METADATA_KEY).getBytes(), HoodieRollingStatMetadata.class);
        inserts = 0;
        upserts = 0;
        for (Map.Entry<String, Map<String, HoodieRollingStat>> pstat : rollingStatMetadata.getPartitionToRollingStats().entrySet()) {
            for (Map.Entry<String, HoodieRollingStat> stat : pstat.getValue().entrySet()) {
                // No new file id should be created, all the data should be written to small files already there
                assertTrue(fileIdToInsertsMap.containsKey(stat.getKey()));
                inserts += stat.getValue().getInserts();
                upserts += stat.getValue().getUpserts();
            }
        }
        Assert.assertEquals(inserts, 600);
        Assert.assertEquals(upserts, 600);
    }
}

@Test
public void testRollbackForInflightCompaction() throws Exception {
    // Rollback inflight compaction
    HoodieWriteConfig cfg = getConfig(false);
    try (HoodieWriteClient client = getHoodieWriteClient(cfg, true);
        HoodieReadClient readClient = getHoodieReadClient(cfg.getBasePath())) {
        String firstInstantTime = "001";
        String secondInstantTime = "004";
        String compactionInstantTime = "005";
        int numRecs = 2000;
        List<HoodieRecord> records = dataGen.generateInserts(firstInstantTime, numRecs);
        runNextDeltaCommits(client, readClient, Arrays.asList(firstInstantTime, secondInstantTime), records, cfg, true, new ArrayList<>());
        // Schedule compaction but do not run them
        scheduleCompaction(compactionInstantTime, client, cfg);
        HoodieTableMetaClient metaClient = new HoodieTableMetaClient(jsc.hadoopConfiguration(), cfg.getBasePath());
        HoodieInstant pendingCompactionInstant = metaClient.getActiveTimeline().filterPendingCompactionTimeline().firstInstant().get();
        assertEquals("Pending Compaction instant has expected instant time", pendingCompactionInstant.getTimestamp(), compactionInstantTime);
        assertEquals("Pending Compaction instant has expected state", pendingCompactionInstant.getState(), State.REQUESTED);
        moveCompactionFromRequestedToInflight(compactionInstantTime, cfg);
        // Reload and rollback inflight compaction
        metaClient = new HoodieTableMetaClient(jsc.hadoopConfiguration(), cfg.getBasePath());
        HoodieTable hoodieTable = HoodieTable.getHoodieTable(metaClient, cfg, jsc);
        // hoodieTable.rollback(jsc,
        //    new HoodieInstant(true, HoodieTimeline.COMPACTION_ACTION, compactionInstantTime), false);
        client.rollbackInflightCompaction(new HoodieInstant(State.INFLIGHT, HoodieTimeline.COMPACTION_ACTION, compactionInstantTime), hoodieTable);
        metaClient = new HoodieTableMetaClient(jsc.hadoopConfiguration(), cfg.getBasePath());
        pendingCompactionInstant = metaClient.getCommitsAndCompactionTimeline().filterPendingCompactionTimeline().getInstants().findFirst().get();
        assertEquals("compaction", pendingCompactionInstant.getAction());
        assertEquals(State.REQUESTED, pendingCompactionInstant.getState());
        assertEquals(compactionInstantTime, pendingCompactionInstant.getTimestamp());
        // We indirectly test for the race condition where a inflight instant was first deleted then created new. Every
        // time this happens, the pending compaction instant file in Hoodie Meta path becomes an empty file (Note: Hoodie
        // reads compaction plan from aux path which is untouched). TO test for regression, we simply get file status
        // and look at the file size
        FileStatus fstatus = metaClient.getFs().getFileStatus(new Path(metaClient.getMetaPath(), pendingCompactionInstant.getFileName()));
        assertTrue(fstatus.getLen() > 0);
    }
}

