    HoodieWriteClient client = getHoodieWriteClient(cfg);
    testConsistencyCheck(metaClient, commitTime);
    // Rollback of this commit should succeed
    client.rollback(commitTime);
    assertFalse("After explicit rollback, commit file should not be present", HoodieTestUtils.doesCommitExist(basePath, commitTime));
